package main

import (
	"bytes"
	"fmt"
	"sync"
)

// New allocates a fresh buffer only when the pool is empty.
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

// greet builds a string in a pooled buffer instead of allocating one per call.
func greet(name string) string {
	buf := bufPool.Get().(*bytes.Buffer) // borrow (or allocate via New)
	buf.Reset()                          // MUST reset: it may hold old bytes
	defer bufPool.Put(buf)               // return it for the next caller

	buf.WriteString("Hello, ")
	buf.WriteString(name)
	buf.WriteByte('!')
	return buf.String() // copy out before Put reuses the backing array
}

func main() {
	fmt.Println(greet("Ada"))
	fmt.Println(greet("Lin"))
}

