package main

import (
	"fmt"
	"sync"
)

// Pool a *[]byte so Put never boxes a slice header into an interface.
var pool = sync.Pool{
	New: func() any {
		b := make([]byte, 0, 64)
		return &b // store the address, not the value
	},
}

func render(n int) string {
	bp := pool.Get().(*[]byte) // borrow the pointer
	b := (*bp)[:0]             // reset length, keep the backing array
	for i := 0; i < n; i++ {
		b = append(b, 'x')
	}
	out := string(b) // copy out before returning the buffer
	*bp = b          // store any grown slice back through the pointer
	pool.Put(bp)     // allocation-free: we Put a pointer, not a header
	return out
}

func main() {
	fmt.Println(render(3))
	fmt.Println(render(5))
}

